import PricingPlanSwitch from '@/components/tweenui/pricing-plan-switch';

export default function Page() {
  return <PricingPlanSwitch />;
}

import PricingPlanSwitch from '@/components/tweenui/pricing-plan-switch';

const plans = [
  {
    id: 'starter',
    name: 'Starter',
    subtitle: 'For early-stage teams',
    description: 'Core automation and a shared workspace to keep momentum.',
    monthly: 2500,
    yearly: 25000,
    includedCount: 5,
  },
  {
    id: 'pro',
    name: 'Pro',
    subtitle: 'For growing teams',
    description: 'Advanced automation, priority workflows, and deeper analytics.',
    monthly: 4190,
    yearly: 41900,
    includedCount: 7,
  },
];

const features = [
  'Unlimited workflows',
  'Team workspace',
  'Email support',
  'Advanced automation',
  'Priority queue',
  'Usage analytics',
  'Role-based access',
];

export default function Page() {
  return <PricingPlanSwitch plans={plans} features={features} ctaHref="/signup" />;
}
